// Package kubeversions carries, per cloud provider, the support window of each Kubernetes minor
// version: when it was released, when ordinary support ends, and when the paid extension ends where
// the provider sells one.
//
// WHY THIS IS A DATASET AND NOT A CONSTANT. Kubernetes ships roughly three minors a year and every
// provider retires them on its own schedule, so any date written into code is wrong within months.
// It is generated by scripts/update-kubeversions.py, on its own cadence, for a reason stated at
// length there: a stale PRICE is a number a little wrong and says so through its asOf stamp, while a
// stale DATE makes a finding fail to fire at all — and an absent finding carries no stamp for a
// reader to distrust.
//
// WHAT THIS PACKAGE WILL NOT DO. It answers "where does this version sit in its provider's support
// window", and nothing else. It does not know what a cluster is running (that is the inventory), it
// does not price anything (that is internal/pricing), and it never guesses a date it was not given:
// an unknown boundary stays empty and Status returns Unknown rather than assuming the version is
// fine. GKE's extended column is empty by construction — the source's field there does not mean what
// it means for EKS and AKS, and filling it would put a date behind a claim nobody published.
package kubeversions

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Window is one minor version's support window with one provider. Dates are "YYYY-MM-DD", and an
// empty string is UNKNOWN — never "no limit" and never "already passed".
type Window struct {
	Minor        string
	Released     string
	StandardEnds string
	ExtendedEnds string
}

// Status is where a version sits in its window on a given day.
type Status string

const (
	// StatusUnknown means the table has no window for this (provider, minor), or the window has no
	// boundary to compare against. It is NOT a synonym for supported: a version we cannot place is a
	// version about which nothing may be claimed.
	StatusUnknown Status = "unknown"
	// StatusSupported — inside ordinary support.
	StatusSupported Status = "supported"
	// StatusExtended — past ordinary support, inside the provider's paid extension. This is the state
	// that costs money and looks like nothing from inside the cluster.
	StatusExtended Status = "extended"
	// StatusUnsupported — past the extension too, or past ordinary support where the provider sells
	// no extension.
	StatusUnsupported Status = "unsupported"
)

// AsOf is the day the table was fetched, "YYYY-MM-DD".
func AsOf() string { return asOf }

// ProviderName is how a person writes the provider this table is keyed by.
//
// THE KEY IS NOT A NAME. These tables are keyed aws | azure | gcp — a different vocabulary from
// Cluster.Provider's eks | aks | gke — and the key was interpolated straight into prose: the reference
// document's own cover carried "Kubernetes 1.31 is past aws's ordinary support window", and four of that
// finding's evidence lines read the same way. A title travels to the cover, the terminal, the app, the
// Markdown export, SARIF and a ticket, and every other cost sentence in the product says "AWS" because the
// renderer has cloudName — which a rule cannot import, and should not have to.
//
// An unrecognised key comes back unchanged. Printing it is honest; inventing a name for it is not.
func ProviderName(key string) string {
	switch key {
	case "aws":
		return "AWS"
	case "azure":
		return "Azure"
	case "gcp":
		return "Google Cloud"
	default:
		return key
	}
}

// Minor reduces a reported server version to "major.minor".
//
// A cluster reports things like "v1.29.8-eks-a1b2c3" or "1.28.14+vmware.1". Everything after the
// second component is provider build detail that no support table is keyed by. Returns "" when the
// input carries no recognisable major.minor, which callers must treat as unknown rather than as a
// version that happens not to be listed.
func Minor(serverVersion string) string {
	v := strings.TrimPrefix(strings.TrimSpace(serverVersion), "v")
	parts := strings.FieldsFunc(v, func(r rune) bool { return r == '.' || r == '-' || r == '+' })
	if len(parts) < 2 {
		return ""
	}
	for _, p := range parts[:2] {
		if p == "" {
			return ""
		}
		for _, c := range p {
			if c < '0' || c > '9' {
				return ""
			}
		}
	}
	return parts[0] + "." + parts[1]
}

// For returns the window for a provider's minor version. provider is the normalized cloud name
// ("aws", "azure", "gcp") or "upstream".
func For(provider, minor string) (Window, bool) {
	byMinor, ok := windows[strings.ToLower(strings.TrimSpace(provider))]
	if !ok {
		return Window{}, false
	}
	w, ok := byMinor[minor]
	return w, ok
}

// Providers is every provider key the table holds, sorted.
func Providers() []string {
	out := make([]string, 0, len(windows))
	for p := range windows {
		out = append(out, p)
	}
	sort.Strings(out)
	return out
}

// Windows is a provider's whole table, oldest minor first — what the landing's deadline calculator carries,
// so the page and every reading answer from one table.
func Windows(provider string) []Window {
	byMinor := windows[strings.ToLower(strings.TrimSpace(provider))]
	out := make([]Window, 0, len(byMinor))
	for _, w := range byMinor {
		out = append(out, w)
	}
	sort.Slice(out, func(i, j int) bool {
		var ai, aj, bi, bj int
		fmt.Sscanf(out[i].Minor, "%d.%d", &ai, &aj)
		fmt.Sscanf(out[j].Minor, "%d.%d", &bi, &bj)
		return ai < bi || (ai == bi && aj < bj)
	})
	return out
}

// NewestMinor is the newest minor version a provider's table knows — for "upstream", the newest Kubernetes
// release as of AsOf. A version past it had not been released when the table was generated, so nothing about it
// is known here.
func NewestMinor(provider string) (string, bool) {
	byMinor, ok := windows[strings.ToLower(strings.TrimSpace(provider))]
	if !ok || len(byMinor) == 0 {
		return "", false
	}
	best, bMaj, bMin := "", -1, -1
	for m := range byMinor {
		var maj, mn int
		if _, err := fmt.Sscanf(m, "%d.%d", &maj, &mn); err != nil {
			continue
		}
		if maj > bMaj || (maj == bMaj && mn > bMin) {
			best, bMaj, bMin = m, maj, mn
		}
	}
	return best, best != ""
}

// StatusOn places a version in its window on the given day.
//
// The comparison is INCLUSIVE of the end date: a provider's published end-of-support day is the last
// day it is supported, so a cluster is only past it from the following day. Getting that backwards
// would fire a finding one day early on every cluster in the world that reads this on the boundary.
func StatusOn(provider, minor string, day time.Time) (Status, Window) {
	w, ok := For(provider, minor)
	if !ok {
		return StatusUnknown, Window{}
	}
	std, okStd := parseDay(w.StandardEnds)
	if !okStd {
		return StatusUnknown, w
	}
	d := day.UTC().Truncate(24 * time.Hour)
	if !d.After(std) {
		return StatusSupported, w
	}
	ext, okExt := parseDay(w.ExtendedEnds)
	if !okExt {
		// No extension published for this provider. Past standard support is unsupported, and the
		// caller must not read that as "and therefore free" — it is a different claim than extended.
		return StatusUnsupported, w
	}
	if !d.After(ext) {
		return StatusExtended, w
	}
	return StatusUnsupported, w
}

func parseDay(s string) (time.Time, bool) {
	if s == "" {
		return time.Time{}, false
	}
	t, err := time.Parse("2006-01-02", s)
	if err != nil {
		return time.Time{}, false
	}
	return t.UTC(), true
}
